export function VicePresidentCard(n,i){const t=n.contributions.map(n=>`<li>${n}</li>`).join(""),a=n.interestingFacts.map(n=>`<p>💡 ${n}</p>`).join("");return`\n        <div class="vp-card" id="vp-${i}">\n            <div class="vp-card-header">\n                <div class="vp-portrait">\n                    <img src="${n.portrait}" alt="Portrait of ${n.name}" loading="lazy" />\n                </div>\n                <div class="vp-title">\n                    <h3>${n.name}</h3>\n                    <p class="vp-term-label">${i+1}${getOrdinal(i+1)} Vice President of India</p>\n                    <p class="vp-meta"><strong>Election:</strong> ${n.electionYear}</p>\n                    <p class="vp-meta"><strong>Term:</strong> ${n.termStart} – ${n.termEnd}</p>\n                </div>\n            </div>\n            <div class="vp-card-body">\n                <div class="vp-section">\n                    <h4>Political Background</h4>\n                    <p>${n.politicalBackground}</p>\n                </div>\n                <div class="vp-section">\n                    <h4>Role in Rajya Sabha</h4>\n                    <p>${n.rajyaSabhaRole}</p>\n                </div>\n                <div class="vp-section">\n                    <h4>Major Contributions</h4>\n                    <ul>${t}</ul>\n                </div>\n                <div class="vp-section vp-facts">\n                    <h4>Interesting Facts</h4>\n                    ${a}\n                </div>\n            </div>\n        </div>\n    `}function getOrdinal(n){const i=["th","st","nd","rd"],t=n%100;return i[(t-20)%10]||i[t]||i[0]}